import{_ as r,C as i,o as l,c as d,j as e,a as s,E as n,a2 as a}from"./chunks/framework.BSl-aDiU.js";const P=JSON.parse('{"title":"3. Rules & mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/rules.md","filePath":"gdd/rules.md"}'),h={name:"gdd/rules.md"},g={id:"_3-1-the-board-hangar",tabindex:"-1"},p={id:"_3-2-fighters",tabindex:"-1"},u={id:"_3-3-flight-zone",tabindex:"-1"},f={id:"_3-4-enemies",tabindex:"-1"},m={id:"_3-5-stages",tabindex:"-1"},b={id:"_3-6-winning-and-losing",tabindex:"-1"};function c(y,t,w,v,T,_){const o=i("Badge");return l(),d("div",null,[t[18]||(t[18]=e("h1",{id:"_3-rules-mechanics",tabindex:"-1"},[s("3. Rules & mechanics "),e("a",{class:"header-anchor",href:"#_3-rules-mechanics","aria-label":'Permalink to "3. Rules & mechanics"'},"​")],-1)),t[19]||(t[19]=e("p",null,[s("All numbers on this page come from "),e("code",null,"src/game/rules.ts"),s(" (game rules) and "),e("code",null,"src/game/layout.ts"),s(" (screen and timings). Change them there first, then here.")],-1)),e("h2",g,[t[0]||(t[0]=s("3.1 The board (hangar) ",-1)),n(o,{type:"tip",text:"Live"}),t[1]||(t[1]=s()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#_3-1-the-board-hangar","aria-label":'Permalink to "3.1 The board (hangar) <Badge type="tip" text="Live" />"'},"​",-1))]),t[20]||(t[20]=a("<ul><li>A rectangular grid; <strong>each level sets its own size</strong>.</li><li>At the start of a level <strong>every cell holds a fighter or a wall</strong>: no empty cells.</li><li>The hangar is as compact as possible: rows and columns differ by at most 1, and there are fewer walls than the grid&#39;s shorter side (otherwise a smaller grid would fit). The level checker enforces both rules.</li><li>Cells are square: <code>min(720 / columns, 565 / rows, 112)</code> px, and the board is centred horizontally under the flight zone.</li><li><strong>Walls</strong> cannot be tapped and never move. They only block paths.</li></ul>",1)),e("h2",p,[t[3]||(t[3]=s("3.2 Fighters ",-1)),n(o,{type:"tip",text:"Live"}),t[4]||(t[4]=s()),t[5]||(t[5]=e("a",{class:"header-anchor",href:"#_3-2-fighters","aria-label":'Permalink to "3.2 Fighters <Badge type="tip" text="Live" />"'},"​",-1))]),t[21]||(t[21]=a('<table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Colour</td><td>One of 8: Red, Blue, Green, Yellow, Purple, Orange, Cyan, Pink</td></tr><tr><td>Ammo</td><td><strong>18</strong> by default; a level can override it per cell</td></tr><tr><td>Bullet colour</td><td>Same as the fighter</td></tr><tr><td>Damage</td><td>1 hit point per bullet</td></tr></tbody></table><h3 id="launching" tabindex="-1">Launching <a class="header-anchor" href="#launching" aria-label="Permalink to &quot;Launching&quot;">​</a></h3><p>The player taps a fighter. It can launch only when there is a <strong>path out of the top edge of the board</strong> that passes through <strong>empty cells only</strong>: other fighters and walls block it. Paths move up, down, left and right (no diagonals), and the game uses the shortest one. Because the hangar starts full, only the top row can launch at first, and every launch opens space for the fighters behind it.</p><ul><li>Fighters with a path are drawn bright. Blocked fighters are dimmed to 45% opacity.</li><li>Tapping a blocked fighter: it shakes and the toast <em>&quot;No way out: clear a path to the top&quot;</em> appears.</li><li>Tapping when the flight zone is full: it shakes, the toast <em>&quot;Flight zone full&quot;</em> appears and the capacity text pulses.</li><li>On launch the fighter&#39;s cell becomes empty at once (it can unblock others straight away). It taxis along the path at <strong>70 ms per cell</strong>, then climbs to the flight zone in 280 ms.</li></ul>',4)),e("h2",u,[t[6]||(t[6]=s("3.3 Flight zone ",-1)),n(o,{type:"tip",text:"Live"}),t[7]||(t[7]=s()),t[8]||(t[8]=e("a",{class:"header-anchor",href:"#_3-3-flight-zone","aria-label":'Permalink to "3.3 Flight zone <Badge type="tip" text="Live" />"'},"​",-1))]),t[22]||(t[22]=a('<ul><li>Holds at most <strong>5 fighters</strong>, counting fighters still taxiing. There are no visible slots: only the text <code>Flight zone n/5</code>, which turns red at 5/5.</li><li>Fighters with nothing to shoot patrol left and right between x = 70 and x = 710 at a random speed of <strong>150–230 px/s</strong>, bouncing at the edges. They never leave the zone to attack.</li></ul><h3 id="flight-zone-hp" tabindex="-1">Flight zone HP <a class="header-anchor" href="#flight-zone-hp" aria-label="Permalink to &quot;Flight zone HP&quot;">​</a></h3><p>The flight zone is what the player protects. It has a pool of HP shown as <code>HP n/max</code> with a bar (green, then yellow below 50%, red below 25%).</p><blockquote><p><strong>Zone HP = hpPerEnemy × enemies in the level</strong>, where a boss counts as <strong>10</strong> enemies.</p></blockquote><p><code>hpPerEnemy</code> is set per level: <strong>40</strong> on the easiest level, down to <strong>20</strong> on the hardest (the checker only allows 20–40). A level can also add a flat <code>zoneHpBonus</code> on top for hand tuning. Each enemy bullet that reaches the flight zone takes <strong>10 HP</strong> and flashes the zone red. At 0 HP the level is lost.</p><h3 id="shooting" tabindex="-1">Shooting <a class="header-anchor" href="#shooting" aria-label="Permalink to &quot;Shooting&quot;">​</a></h3><ul><li>A fighter only shoots enemies <strong>of its own colour</strong> that are <strong>not shielded</strong> (see 3.4). With no such enemy it keeps patrolling without firing.</li><li><strong>Line up, then fire.</strong> A fighter with a target first moves under it at <strong>1100 px/s</strong> (aiming at a random point within the middle 44% of the target&#39;s width), and fires only once it is within 6 px of that point.</li><li>Bullets fly <strong>straight up</strong> at <strong>1900 px/s</strong>. Once a bullet is within <strong>90 px</strong> of its target it steers into the target&#39;s centre, so it never misses.</li><li>Fire rate: one bullet every <strong>0.11 s</strong> per fighter.</li><li><strong>Target order:</strong> the frontmost unshielded target of the fighter&#39;s colour (lowest on screen), then left to right.</li><li><strong>No wasted bullets.</strong> A fighter only fires if the target still has hit points that bullets already in the air won&#39;t cover. Among fighters of the same colour, the one that arrived <strong>first</strong> gets first claim on the hit points it can reach, so it empties and frees its slot first. A later fighter only fires at whatever the earlier ones can&#39;t cover.</li><li>When a fighter fires its last bullet it <strong>flies off the top of the screen</strong> and its slot is free immediately.</li></ul>',7)),e("h2",f,[t[9]||(t[9]=s("3.4 Enemies ",-1)),n(o,{type:"tip",text:"Live"}),t[10]||(t[10]=s()),t[11]||(t[11]=e("a",{class:"header-anchor",href:"#_3-4-enemies","aria-label":'Permalink to "3.4 Enemies <Badge type="tip" text="Live" />"'},"​",-1))]),t[23]||(t[23]=a('<h3 id="front-first-shielding" tabindex="-1">Front first: shielding <a class="header-anchor" href="#front-first-shielding" aria-label="Permalink to &quot;Front first: shielding&quot;">​</a></h3><p>A target (enemy or boss part) is <strong>shielded</strong> while a living target sits <strong>in front of it</strong> (lower on screen) and overlaps it sideways by more than 8 px. Shielded targets can&#39;t be shot, even by a fighter of the right colour, and are drawn at 60% opacity. The ones in front have to go down first. This applies to boss parts too.</p><h3 id="regular-enemies" tabindex="-1">Regular enemies <a class="header-anchor" href="#regular-enemies" aria-label="Permalink to &quot;Regular enemies&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Size</th><th>Hit points</th><th>Display width</th></tr></thead><tbody><tr><td>Small</td><td><strong>3</strong></td><td>74 px</td></tr><tr><td>Medium</td><td><strong>6</strong></td><td>100 px</td></tr><tr><td>Large</td><td><strong>9</strong></td><td>128 px</td></tr></tbody></table><ul><li>Each enemy has one colour and shows its remaining hit points.</li><li>A stage&#39;s enemies are packed into centred rows in the order the level lists them: the first groups end up at the back (top), the last at the front.</li><li>They fly in from the top over 650 ms and sway together ±22 px.</li><li><strong>They shoot back:</strong> one bullet straight down every <strong>3 s</strong> (the first shot comes at a random time within the first 0.5–3 s, so a formation doesn&#39;t fire in unison). Enemy bullets travel at <strong>460 px/s</strong>.</li><li>At 0 hit points an enemy explodes in its colour.</li></ul><h3 id="boss" tabindex="-1">Boss <a class="header-anchor" href="#boss" aria-label="Permalink to &quot;Boss&quot;">​</a></h3><ul><li>Appears <strong>only in the last stage</strong> of a level (the level checker rejects a boss anywhere else).</li><li>A large grey hull carrying <strong>2–8 armour parts</strong>. Each part has its own colour, a large pool of hit points (18–36 in the shipped levels) and <strong>its own weapon</strong>.</li><li>Parts fill the slots below in order. The slot sets the part&#39;s position and default weapon (a level can override the weapon):</li></ul><table tabindex="0"><thead><tr><th>Slot</th><th>Position (from boss centre)</th><th>Weapon</th><th>Every</th><th>Bullets</th></tr></thead><tbody><tr><td>1. Left wing</td><td>−180, 0</td><td>Spread (fan, 14° apart)</td><td>4 s</td><td>3</td></tr><tr><td>2. Right wing</td><td>+180, 0</td><td>Spread</td><td>4 s</td><td>3</td></tr><tr><td>3. Core</td><td>0, −20</td><td>Spread</td><td>5 s</td><td>5</td></tr><tr><td>4. Nose</td><td>0, +130</td><td>Burst (straight down, 0.12 s apart)</td><td>3.5 s</td><td>4</td></tr><tr><td>5. Left engine</td><td>−105, −140</td><td>Single</td><td>1.5 s</td><td>1</td></tr><tr><td>6. Right engine</td><td>+105, −140</td><td>Single</td><td>1.5 s</td><td>1</td></tr><tr><td>7. Left gun pod</td><td>−300, −70</td><td>Aimed at a fighter</td><td>2.5 s</td><td>2</td></tr><tr><td>8. Right gun pod</td><td>+300, −70</td><td>Aimed at a fighter</td><td>2.5 s</td><td>2</td></tr></tbody></table><ul><li>Shielding makes the order strategic: the nose shields the core, and the wings and core shield the engines. The gun pods are never shielded, so the fast aimed guns can be silenced first.</li><li>When a part reaches 0 it explodes, the screen shakes, the part <strong>stops firing</strong> and stays on the hull <strong>burnt out</strong> (darkened to 28% of its colour).</li><li>When every part is destroyed the boss dies: a chain of 8 explosions, a longer screen shake, then it fades out.</li></ul><h3 id="enemy-bullets" tabindex="-1">Enemy bullets <a class="header-anchor" href="#enemy-bullets" aria-label="Permalink to &quot;Enemy bullets&quot;">​</a></h3><ul><li>An enemy bullet that reaches the flight zone costs zone HP (see 3.3). Bullets that leave the screen sideways do nothing.</li><li><strong>If the enemy or boss part that fired a bullet is destroyed, its bullets still in the air vanish.</strong></li><li>Enemy bullets don&#39;t hit fighters, and fighters&#39; bullets don&#39;t hit enemy bullets.</li></ul>',11)),e("h2",m,[t[12]||(t[12]=s("3.5 Stages ",-1)),n(o,{type:"tip",text:"Live"}),t[13]||(t[13]=s()),t[14]||(t[14]=e("a",{class:"header-anchor",href:"#_3-5-stages","aria-label":'Permalink to "3.5 Stages <Badge type="tip" text="Live" />"'},"​",-1))]),t[24]||(t[24]=a("<ul><li>A level is a sequence of stages. Each stage has a fixed set of enemies; the last stage may be a boss (optionally with escorts).</li><li>The HUD shows <code>Stage n/total</code>. A banner announces each stage (<code>Stage n</code>, or <code>BOSS</code> + its name).</li><li>Fighters start shooting, and enemies start firing, once the whole stage has flown in.</li><li>When every enemy in the stage is destroyed, the next stage flies in after <strong>0.7 s</strong> (1.4 s after a boss).</li></ul>",1)),e("h2",b,[t[15]||(t[15]=s("3.6 Winning and losing ",-1)),n(o,{type:"tip",text:"Live"}),t[16]||(t[16]=s()),t[17]||(t[17]=e("a",{class:"header-anchor",href:"#_3-6-winning-and-losing","aria-label":'Permalink to "3.6 Winning and losing <Badge type="tip" text="Live" />"'},"​",-1))]),t[25]||(t[25]=a('<table tabindex="0"><thead><tr><th>Result</th><th>Condition</th></tr></thead><tbody><tr><td><strong>Level cleared!</strong></td><td>The last stage is destroyed. The panel shows the zone HP left.</td></tr><tr><td><strong>Flight zone destroyed</strong></td><td>Zone HP reaches 0.</td></tr><tr><td><strong>Out of space</strong></td><td>The flight zone is full (5/5), no fighter in it has anything to shoot, and nothing is in the air.</td></tr><tr><td><strong>No moves left</strong></td><td>The flight zone has free slots but no fighter on the board can reach the top, and nothing can shoot.</td></tr></tbody></table><p>&quot;Out of space&quot; and &quot;No moves left&quot; are only declared after the game has been in that state for <strong>0.6 s</strong>, so a slot that is about to free up never counts as a loss.</p><p>Because each colour&#39;s ammo equals that colour&#39;s enemy hit points (see <a href="./levels#balance-rule">Levels &amp; balance</a>), a fighter never ends a level with ammo left over, and the board is always empty when a level is won. Zone HP turns this into a race: every second a stage stays alive, its enemies keep firing.</p>',3))])}const k=r(h,[["render",c]]);export{P as __pageData,k as default};
